import{_ as s,c as n,o as e,ag as p}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Authentik-Backup","description":"","frontmatter":{"title":"Authentik-Backup"},"headers":[],"relativePath":"infrastructure/authentik-backup.md","filePath":"infrastructure/authentik-backup.md","lastUpdated":null}'),i={name:"infrastructure/authentik-backup.md"};function r(t,a,l,c,u,o){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="authentik-backup" tabindex="-1">Authentik-Backup <a class="header-anchor" href="#authentik-backup" aria-label="Permalink to &quot;Authentik-Backup&quot;">​</a></h1><h2 id="backing-up-authentik-server" tabindex="-1">Backing Up Authentik Server <a class="header-anchor" href="#backing-up-authentik-server" aria-label="Permalink to &quot;Backing Up Authentik Server&quot;">​</a></h2><p>This guide provides steps to back up an Authentik server, including PostgreSQL and Redis databases, and sync the backup to a Proxmox server for redundancy.</p><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>This process includes:</p><ul><li><p>Backing up critical components of the Authentik server, such as databases and configuration files.</p></li><li><p>Compressing backups into a single tarball for easy transfer and storage.</p></li><li><p>Encrypting backups for additional security (optional).</p></li><li><p>Syncing backups from the Authentik server to the Proxmox server.</p></li></ul><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li><p>Access to the Authentik server and Proxmox server.</p></li><li><p>Authentik server&#39;s IP address or hostname and a user with appropriate SSH privileges.</p></li><li><p>Tools: <code>rsync</code>, <code>ssh</code>, and required Docker utilities installed on both servers.</p></li><li><p>Backup storage location on Proxmox server.</p></li><li><p>Remote storage (e.g., pCloud) for redundancy.</p></li></ul><h3 id="backup-script" tabindex="-1">Backup Script <a class="header-anchor" href="#backup-script" aria-label="Permalink to &quot;Backup Script&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Define variables</span></span>
<span class="line"><span>BACKUP_DIR=&quot;/datadrive/Backups&quot;</span></span>
<span class="line"><span>VZ_DIR=&quot;/var/lib/vz/dump&quot;</span></span>
<span class="line"><span>BACKUP_REMOTE=&quot;pcloud:Backups/Server-Backups&quot;</span></span>
<span class="line"><span>VZ_REMOTE=&quot;pcloud:Backups/Server-Backups/VZDUMPS&quot;</span></span>
<span class="line"><span>LOCAL_BACKUP_DIR=&quot;/datadrive/Backups&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Authentik variables</span></span>
<span class="line"><span>AUTHENTIK_REMOTE_USER=&quot;root&quot;</span></span>
<span class="line"><span>AUTHENTIK_REMOTE_HOST=&quot;192.168.X.Y&quot; # Replace with Authentik server&#39;s IP</span></span>
<span class="line"><span>AUTHENTIK_REMOTE_BACKUP_DIR=&quot;/home/authentik/authentik/authentik_backups&quot;</span></span>
<span class="line"><span>TIMESTAMP=$(date +&quot;%Y%m%d%H%M%S&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Ensure remote backup directory exists</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST &quot;mkdir -p $AUTHENTIK_REMOTE_BACKUP_DIR&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Backup PostgreSQL Database</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST \\</span></span>
<span class="line"><span>&quot;docker exec -i authentik-postgresql-1 /usr/local/bin/pg_dump --username authentik authentik &gt; $AUTHENTIK_REMOTE_BACKUP_DIR/postgres-back-$TIMESTAMP.sql&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Save Redis Database</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST &quot;docker exec -i authentik-redis-1 redis-cli save&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Copy Redis Dump</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST \\</span></span>
<span class="line"><span>&quot;docker cp authentik-redis-1:/data/dump.rdb $AUTHENTIK_REMOTE_BACKUP_DIR/redis-backup-$TIMESTAMP.rdb&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Create Tarball of Necessary Files</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST \\</span></span>
<span class="line"><span>&quot;tar czvf $AUTHENTIK_REMOTE_BACKUP_DIR/authentik-backup-$TIMESTAMP.tar.gz -C /home/authentik/authentik authentik docker-compose.yml certs&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Sync backups from Authentik server to Proxmox server</span></span>
<span class="line"><span>rsync -avz --progress $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST:$AUTHENTIK_REMOTE_BACKUP_DIR/ $LOCAL_BACKUP_DIR/authentik_backups</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Backup and sync completed successfully.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br></div></div><h3 id="optional-encryption" tabindex="-1">Optional Encryption <a class="header-anchor" href="#optional-encryption" aria-label="Permalink to &quot;Optional Encryption&quot;">​</a></h3><p>To add encryption, use tools like <code>gpg</code> or <code>age</code>. For example:</p><h3 id="gpg" tabindex="-1">GPG <a class="header-anchor" href="#gpg" aria-label="Permalink to &quot;GPG&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Encrypt the tarball with GPG</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST \\</span></span>
<span class="line"><span>&quot;gpg --symmetric --cipher-algo AES2# $AUTHENTIK_REMOTE_BACKUP_DIR/authentik-backup-$TIMESTAMP.tar.gz&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="age" tabindex="-1">age <a class="header-anchor" href="#age" aria-label="Permalink to &quot;age&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Encrypt the tarball with age</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST \\</span></span>
<span class="line"><span>&quot;age -e -a -r default.recipient $AUTHENTIK_REMOTE_BACKUP_DIR/authentik-backup-$TIMESTAMP.tar.gz&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="considerations" tabindex="-1">Considerations <a class="header-anchor" href="#considerations" aria-label="Permalink to &quot;Considerations&quot;">​</a></h3><ol><li><p><strong>Security:</strong> Ensure SSH access to the Authentik server is secure (e.g., use key-based authentication).</p></li><li><p><strong>Automation:</strong> Consider scheduling this script via <code>cron</code> or a similar tool for regular backups.</p></li><li><p><strong>Testing:</strong> Regularly test your backup restoration process to ensure integrity and usability.</p></li></ol><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3>`,19)])])}const h=s(i,[["render",r]]);export{d as __pageData,h as default};
